package ktanesolver.module.modded.regular.necronomicon;
import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service @ModuleInfo(type=ModuleType.THE_NECRONOMICON,id="necronomicon",name="The Necronomicon",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Filter the seven chapters by origin and deity, then follow the wheel priority.",tags={"book","chapters","translation","priority"})
public class NecronomiconSolver extends AbstractModuleSolver<NecronomiconInput,NecronomiconOutput>{
 private static final List<String>ORIGINS=List.of("plateau of leng","sarnath","dylath-leen","yuggoth","r'lyeh"),GODS=List.of("azathoth","nyarlathotep","tsathoggua","yog-sothoth","shub-niggurath","nug and yeb","cthulhu","hastur"),REFERENCES=List.of("true name","alias","family relationship");private static final int[][]PRIORITY={{2,11,21,26,16},{30,3,19,24,23},{33,7,35,12,6},{38,31,13,22,32},{28,37,1,39,5},{29,25,15,17,36},{18,40,10,34,14},{8,27,20,4,9}};
 @Override protected SolveResult<NecronomiconOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,NecronomiconInput input){if(input==null)return failure("Enter the book origin, worshipped god, reference type, and seven chapters");int place=ORIGINS.indexOf(norm(input.origin())),god=GODS.indexOf(norm(input.worshippedGod())),reference=REFERENCES.indexOf(norm(input.referenceType()));if(place<0||god<0||reference<0||input.chapters()==null||input.chapters().size()!=7||new HashSet<>(input.chapters()).size()!=7||input.chapters().stream().anyMatch(c->c==null||c<1||c>40))return failure("Choose valid origin/god/reference values and seven distinct chapters from 1 through 40");List<Integer>chapters=input.chapters().stream().sorted().toList(),valid=chapters.stream().filter(c->valid(c,place,god,reference)).toList();if(valid.isEmpty())return failure("None of the entered chapters meets its eligibility condition; check the translation and chapter list");List<Integer>priority=new ArrayList<>();for(int i=0;i<=place;i++)priority.add(PRIORITY[god][i]);for(int i=god+1;i<8;i++)priority.add(PRIORITY[i][place]);for(int i=0;i<god;i++)priority.add(PRIORITY[i][place]);int chapter=priority.stream().filter(valid::contains).findFirst().orElse(valid.get(0)),page=chapters.indexOf(chapter)+1;storeState(module,"necronomiconChapters",List.copyOf(chapters));return success(new NecronomiconOutput(chapter,page,List.copyOf(valid),List.copyOf(priority),"page "+page));}
 private static boolean valid(int c,int p,int g,int r){return switch(c){case 1->g==2||g==4;case 2->g==0;case 3->p==1||p==3;case 4->g==4||g==7;case 5->p==1||p==4;case 6->g!=1;case 7->g==2;case 8->p==0;case 9->p==0||p==4;case 10->p==2;case 11->p==1;case 12->p==2||p==3;case 13->p==1||p==2;case 14->p==4||g==6;case 15->p==2||p==4;case 16->g==0||g==1;case 17->g==3||g==5;case 18->p==0||p==2;case 19->g==1;case 20->g==6||g==7;case 21->g==0||g==1||g==3||g==4;case 22->g==3;case 23->g==1;case 24->p==0||p==3;case 25->g==2||g==5;case 26->r==0;case 27->p==0||p==1;case 28->g>=4;case 29->g==5;case 30->g==1;case 31->g==3;case 32->p==3||p==4;case 33->g==2||g==7;case 34->g==0||g==6;case 35->p<=2;case 36->p==3||p==4;case 37->r==2;case 38->r==1;case 39->p==3;default->true;};}private static String norm(String s){return s==null?"":s.trim().toLowerCase(Locale.ROOT).replace('’','\'');}
}
